-- 1123: Blog post — "GitHub Foundations Certification in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Github Foundations Certification Training (TGS-2025053207).
--       Backdated to 2025-09-16 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $1,000.00, GST $90.00 (9%), baseline nett $590.00
--     (SG/PR 21+, 50%), MCES/SME nett $390.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 25 Feb 2025 - 24 Feb 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Software Configuration (ICT-DIT-3014-1.1).
--   * Exam weightings from the official study guide, skills measured as of Jan 2026.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/github/github-foundations
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'GitHub Foundations Certification in Singapore: Exam Domains, Funding and Practice Exams', 'github-foundations-certification-singapore-guide', 'GitHub Foundations is the Microsoft credential for developers, QA engineers and anyone collaborating in a shared codebase. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $590 nett, or $390 for Singapore Citizens aged 40 and above &mdash; and shows what the 2 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>GitHub Foundations</strong> is the Microsoft credential for developers, QA engineers and anyone collaborating in a shared codebase. This guide covers what the exam measures, what the 2 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$590</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$390</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why GitHub Foundations is worth sitting</h2><p>Git is the default way software gets written, and GitHub is where most of it lives. But a great many working developers learned Git by copying three commands from a colleague and have never understood branching, pull requests or what actually happens on a merge conflict. GitHub Foundations fixes that, and adds the collaboration, security and automation features most teams underuse.</p><ul><li><strong>The exam was significantly revised in January 2026</strong> and now covers seven skill areas, including GitHub Actions, Copilot and Codespaces.</li><li><strong>It moved to Microsoft Learn and Pearson VUE</strong>, aligning it with the rest of the Microsoft certification estate.</li><li><strong>Relevant beyond developers.</strong> Technical writers, QA and data teams all work in repositories now.</li><li><strong>It is the entry point to the GitHub certification track</strong>, which continues into Actions, Advanced Security and Administration.</li></ul><p>The course is mapped to the Skills Framework under <strong>Software Configuration</strong> (TSC code ICT-DIT-3014-1.1), and leads to roles such as Software Developer, Version Control Specialist, DevOps Engineer, Configuration Manager. <a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html">Check the funding you qualify for</a>.</p><h2>The GitHub Foundations exam at a glance</h2><table><tbody><tr><td>Exam</td><td>GH-900: GitHub Foundations</td></tr><tr><td>Length</td><td>100 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled)</td></tr><tr><td>Delivered by</td><td>Pearson VUE, via Microsoft Learn</td></tr><tr><td>Note</td><td>The exam was significantly revised in January 2026</td></tr></tbody></table><h2>GitHub Foundations exam domains and weightings</h2><p>GitHub Foundations was significantly revised in January 2026 and now has seven skill areas. Older study material citing 75 questions, 120 minutes or a five-domain split is out of date.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Understand Git and GitHub basics</td><td>25&ndash;30%</td></tr><tr><td>Work with GitHub repositories</td><td>10&ndash;15%</td></tr><tr><td>Collaborate using GitHub</td><td>10&ndash;15%</td></tr><tr><td>Apply modern development practices</td><td>10&ndash;15%</td></tr><tr><td>Manage projects with GitHub</td><td>5&ndash;10%</td></tr><tr><td>Understand privacy, security, and administration</td><td>10&ndash;15%</td></tr><tr><td>Explore the GitHub community</td><td>5&ndash;10%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of Jan 2026.</em></p><h2>What the WSQ course covers</h2><p>The 2 days (16 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html"><strong>WSQ - Github Foundations Certification Training</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Introduction to Git and GitHub</li><li>Working with GitHub Repository</li><li>Collaboration Features</li><li>Modern Development</li><li>GitHub Project</li><li>Privacy, Security and Administration</li></ol><h2>Practise before you book the exam</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/github/github-foundations">GitHub Foundations practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for GitHub Foundations training</h2><p>The full fee is $1,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$1,090</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$590</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$390</strong></td></tr></tbody></table><p><em>GST of $90 is charged at 9% on the full course fee of $1,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>25 Feb 2025</strong> to <strong>24 Feb 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 2 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit GitHub Foundations</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after GitHub Foundations</h2><p>GitHub offers further certifications in Actions, Advanced Security and Administration. If your interest is the wider delivery pipeline, <a href="https://www.tertiarycourses.com.sg/wsq-designing-and-implementing-microsoft-devops-solutions-az-400.html">AZ-400</a> covers DevOps end to end. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need to know Git already?</summary><div class="mmd-faq-a"><p>No. The course starts with version-control fundamentals and basic Git commands before moving on to GitHub collaboration features.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is this exam still current?</summary><div class="mmd-faq-a"><p>Yes. GitHub Foundations (exam GH-900) was significantly revised in January 2026 and now has seven skill areas. Be careful with older study material citing 75 questions or a five-domain split &mdash; those figures are out of date.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The GH-900 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is this course only for programmers?</summary><div class="mmd-faq-a"><p>No. Anyone who collaborates in a repository benefits &mdash; including QA, technical writers, data analysts and engineering managers.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What funding can I use?</summary><div class="mmd-faq-a"><p>Singapore Citizens and PRs aged 21 and above get 50% subsidy, rising to 70% for Citizens aged 40 and above, plus SkillsFuture Credit, PSEA and UTAP.</p></div></details></div><h2>Register for GitHub Foundations training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-github-foundations-certification-training.html"><strong>WSQ - Github Foundations Certification Training</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-16', 'TGS-2025053207', 'TGS-2025053207', 'GitHub Foundations Certification Singapore | GH-900 Exam Guide and WSQ Funding', 'Train for GitHub Foundations GitHub Foundations in Singapore. 2 days WSQ course from $390 nett after funding, full exam domain breakdown, and free practice exams for participants.', 'github foundations course singapore, github foundations certification, github foundations exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, github foundations funding, github foundations training singapore', 'manual-skip-no-share', '2025-09-16 09:00:00', '2025-09-16 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'github-foundations-certification-singapore-guide');

