INSERT INTO `tag` (`name`, `status`) SELECT 'Git', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Git') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Version Control', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Version Control') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'DevOps', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'DevOps') x);
