SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'github-foundations-certification-singapore-guide');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('GitHub', 'Git', 'Version Control', 'DevOps', 'WSQ');

